import {PERSISTENCE_LIMITS} from './react-persistence-contract.js';
// Runs only inside the opaque reviewed document; no persistence grants are provided here.
export function reactPersistentFrameBootstrap({nonce,storageKeys,mount,createDataRuntime,createCapabilities}){
 let port=null,connected=false,initialized=false,stopped=false,sequence=0,capabilities=null;const pending=new Map();
 const plain=v=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.getPrototypeOf(v)===Object.prototype;
 function stop(){if(stopped)return;stopped=true;capabilities?.stop();for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('react_persistence_runtime_stopped'));}pending.clear();port?.close();window.removeEventListener('message',connect);}
 function failure(code){capabilities?.stop();if(!stopped)try{port?.postMessage({id:++sequence,action:'fault',code:typeof code==='string'?code.slice(0,100):'runtime_failed'});}catch{}}
 function request(action,payload){if(stopped||!initialized||pending.size>=PERSISTENCE_LIMITS.queue)return Promise.reject(Error('react_persistence_channel_unavailable'));const id=++sequence;return new Promise((resolve,reject)=>{const timer=action==='confirm'?null:setTimeout(()=>{pending.delete(id);failure('react_persistence_reply_unconfirmed');reject(Error('react_persistence_reply_unconfirmed'));},15000);pending.set(id,{resolve,reject,timer});port.postMessage({id,action,...payload});});}
 function message(event){const m=event.data;if(!plain(m))return;if(m.type==='stop'){stop();return;}if(!initialized){if(m.type!=='init'||JSON.stringify(m.storageKeys)!==JSON.stringify(storageKeys)||!Number.isSafeInteger(m.revision)||m.revision<0||!plain(m.cache)||Object.keys(m).some(k=>!['type','cache','storageKeys','revision'].includes(k)))return;try{initialized=true;const data=createDataRuntime({isActive:()=>!stopped&&(!capabilities||capabilities.isActive()),onFailure:failure});capabilities=createCapabilities({cache:m.cache,storageKeys,enter:data.enter,leave:data.leave,isActive:()=>!stopped&&!data.isFailed(),onFailure:failure,onRecovery:s=>{if(!stopped)port.postMessage({id:++sequence,action:'snapshot',cache:s.cache,pending:s.pending});},onWrite:mutation=>request('write',mutation),onConfirm:text=>request('confirm',{text}),onStatus:s=>{if(!stopped&&s.state==='pending')port.postMessage({id:++sequence,action:'status',state:'pending',pending:s.pending});}});port.postMessage({type:'react-persistent-initialized'});mount({...data,...capabilities.capabilities});}catch{failure('react_persistence_initialization_failed');stop();}return;}
 if(!Number.isSafeInteger(m.id)||!pending.has(m.id)||typeof m.ok!=='boolean')return;const p=pending.get(m.id);pending.delete(m.id);clearTimeout(p.timer);if(m.ok)p.resolve(m.result);else p.reject(Error(typeof m.error==='string'?m.error:'react_persistence_reply_unconfirmed'));}
 function connect(event){if(connected||stopped||event.source!==parent||!plain(event.data)||Object.keys(event.data).length!==2||event.data.type!=='react-persistent-connect'||event.data.nonce!==nonce||event.ports?.length!==1)return;connected=true;window.removeEventListener('message',connect);port=event.ports[0];port.onmessage=message;port.start();}
 document.addEventListener('click',event=>{const link=event.target?.closest?.('a');if(!link)return;event.preventDefault();const href=link.getAttribute('href');if(typeof href==='string'&&/^#[A-Za-z][A-Za-z0-9_-]{0,100}$/.test(href)){const node=document.getElementById(href.slice(1));node?.scrollIntoView({behavior:'auto',block:'start'});node?.focus({preventScroll:true});}},true);
 // Sandboxed forms cannot emit their native submit event. Route only genuine,
 // uncancelled in-frame gestures after React bubbling; never enable native forms.
 const inDocument=node=>node?.ownerDocument===document&&document.documentElement?.contains(node);
 const enabled=node=>!!node&&node.disabled!==true&&!node.matches?.(':disabled');
 function submitForm(form,control,event){if(stopped||!initialized||!capabilities?.isActive()||event.isTrusted!==true||event.defaultPrevented||!inDocument(form)||form.tagName!=='FORM'||!inDocument(control)||control.form!==form||!enabled(control))return;event.preventDefault();if(!form.noValidate&&!control.formNoValidate&&typeof form.checkValidity==='function'&&!form.checkValidity()){form.reportValidity?.();return;}form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));}
 document.addEventListener('click',event=>{if(event.button!==0||event.altKey||event.ctrlKey||event.metaKey||event.shiftKey)return;const control=event.target?.closest?.('button');if(!control||control.type!=='submit')return;submitForm(control.form,control,event);});
 document.addEventListener('keydown',event=>{if(event.key!=='Enter'||event.isComposing||event.keyCode===229||event.repeat||event.altKey||event.ctrlKey||event.metaKey||event.shiftKey)return;const control=event.target;if(control?.tagName!=='INPUT'||!['text','search','number','date'].includes(control.type))return;const form=control.form;if(!form)return;const submitter=[...form.elements].find(node=>node.tagName==='BUTTON'&&node.type==='submit');if(!submitter||submitter.form!==form||!inDocument(submitter)||!enabled(submitter))return;submitForm(form,control,event);});
 document.addEventListener('submit',event=>event.preventDefault(),true);window.addEventListener('message',connect);window.addEventListener('pagehide',stop,{once:true});parent.postMessage({type:'react-persistent-ready',nonce},'*');return {stop};
}
